def db_url():
    try:
        v=st.secrets.get("DATABASE_URL","")
        if v: return str(v).strip()
    except Exception: pass
    p=Path(__file__).with_name("supabase_db_url.txt")
    if p.exists(): return p.read_text(encoding="utf-8").strip()
    return os.environ.get("DATABASE_URL","").strip()

URL=db_url()
if not URL:
    st.error("supabase_db_url.txt가 없습니다.")
    st.stop()

def query(sql,args=()):
    with psycopg.connect(URL) as c:
        with c.cursor() as cur:
            cur.execute(sql,args)
            if not cur.description: return pd.DataFrame()
            cols=[d.name for d in cur.description]
            return pd.DataFrame(cur.fetchall(),columns=cols)

def execute(sql,args=()):
    with psycopg.connect(URL) as c:
        with c.cursor() as cur: cur.execute(sql,args)
        c.commit()

def keyfile(name):
    p=Path(__file__).with_name(name)
    return p.read_text(encoding="utf-8").strip() if p.exists() else ""

def yt_views(video_id):
    key=keyfile("youtube_key.txt")
    if not key: raise RuntimeError("youtube_key.txt가 없습니다.")
    u=f"https://www.googleapis.com/youtube/v3/videos?part=statistics&id={video_id}&key={key}"
    with urllib.request.urlopen(u,timeout=15) as r: obj=json.load(r)
    if not obj.get("items"): raise RuntimeError("YouTube 영상을 찾지 못했습니다.")
    return int(obj["items"][0]["statistics"]["viewCount"])

def milestone(v):
    levels=[1_000_000,5_000_000,10_000_000,20_000_000,50_000_000,100_000_000,200_000_000,300_000_000,500_000_000,1_000_000_000]
    for n in levels:
        if v<n:
            prev=max([x for x in [0]+levels if x<=v])
            pct=(v-prev)/(n-prev)*100 if n>prev else 100
            return n,pct
    n=((v//100_000_000)+1)*100_000_000
    return n,(v%100_000_000)/100_000_000*100

def _compact_m(n):
    if n >= 1_000_000_000:
        return f"{n/1_000_000_000:g}B"
    if n >= 1_000_000:
        return f"{n/1_000_000:g}M"
    if n >= 1_000:
        return f"{n/1_000:g}K"
    return str(int(n))

def card(platform,title,value):
    value=int(value)
    nxt,pct=milestone(value)
    levels=[1_000_000,5_000_000,10_000_000,20_000_000,30_000_000,50_000_000,100_000_000,200_000_000,300_000_000,500_000_000,1_000_000_000]
    achieved=max([x for x in levels if x<=value], default=0)
    prev=max([0]+[x for x in levels if x<=value and x<nxt])
    idx=0 if pct<34 else (1 if pct<67 else 2)
    icon=Image.open(BytesIO(base64.b64decode(RUNNER_ICONS_B64[idx]))).convert("RGBA")
    im=Image.new("RGB",(1200,900),"#fffafb"); d=ImageDraw.Draw(im)
    def _card_font(size, bold=False):
        candidates = [
            "/usr/share/fonts/opentype/noto/NotoSansCJK-Bold.ttc" if bold else "/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc",
            "/usr/share/fonts/opentype/noto/NotoSansCJKkr-Bold.otf" if bold else "/usr/share/fonts/opentype/noto/NotoSansCJKkr-Regular.otf",
            "/usr/share/fonts/truetype/noto/NotoSansKR-Bold.ttf" if bold else "/usr/share/fonts/truetype/noto/NotoSansKR-Regular.ttf",
            "C:/Windows/Fonts/malgunbd.ttf" if bold else "C:/Windows/Fonts/malgun.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "arialbd.ttf" if bold else "arial.ttf",
        ]
        for p in candidates:
            try:
                return ImageFont.truetype(p, size)
            except:
                pass
        return ImageFont.load_default()

    f_platform=_card_font(34, True)
    f_title=_card_font(54, True)
    f_achievement=_card_font(92, True)
    f_label=_card_font(34, True)
    f_footer=_card_font(32, True)

    # pink frame
    d.rounded_rectangle((24,24,1176,876),30,outline="#e3a0b1",width=8)
    d.text((70,58),platform,font=f_platform,fill="#77545d")
    d.text((70,118),title,font=f_title,fill="#382c2f")
    achieved_text=f"{_compact_m(achieved)} 달성!" if achieved else f"{pct:.1f}% 달성!"
    d.text((70,220),achieved_text,font=f_achievement,fill="#c96f87")

    icon.thumbnail((260,250))
    im.paste(icon,(470,330),icon)

    x0,y0,x1,y1=90,620,1110,690
    d.rounded_rectangle((x0,y0,x1,y1),18,fill="#e4e7eb")
    fill=x0+int((x1-x0)*max(0,min(100,pct))/100)
    if fill>x0: d.rounded_rectangle((x0,y0,fill,y1),18,fill="#e3a0b1")
    d.text((90,710),_compact_m(prev),font=f_label,fill="#77545d")
    txt=f"NEXT {_compact_m(nxt)}"
    tw=d.textbbox((0,0),txt,font=f_label)[2]
    d.text((1110-tw,710),txt,font=f_label,fill="#77545d")

    footer="김석진 음원정보팀 1204 Hz"
    fw=d.textbbox((0,0),footer,font=f_footer)[2]
    d.text(((1200-fw)//2,805),footer,font=f_footer,fill="#77545d")
    b=BytesIO(); im.save(b,format="PNG"); return b.getvalue()

def album_filter(df,key):
    if df.empty or "album" not in df.columns: return df
    vals=["ALL"]+sorted([str(x) for x in df.album.dropna().unique() if str(x).strip()])
    a=st.selectbox("Album",vals,key=key)
    return df if a=="ALL" else df[df.album.astype(str)==a]


RUNNER_ICONS_B64 = ['', '', '']
LAST_1204_B64 = ''

def runner(value, platform=""):
    if value is None or pd.isna(value): return
    nxt,pct=milestone(int(value))
    levels=[1_000_000,5_000_000,10_000_000,20_000_000,30_000_000,50_000_000,100_000_000,200_000_000,300_000_000,500_000_000,1_000_000_000]
    prev=max([0]+[x for x in levels if x<=int(value) and x<nxt])

    # User-requested order: icon1 -> icon2 -> icon3.
    idx = 0 if pct < 34 else (1 if pct < 67 else 2)
    sprite=RUNNER_ICONS_B64[idx]

    palette={"YOUTUBE":("#ff4b55","#ffe5e8"),"SPOTIFY":("#1db954","#e0f6e7"),"MELON":("#82c832","#eef8df")}
    fg,bg=palette.get(platform.upper(),("#d97b91","#f4dce2"))
    blocks=24
    filled=max(0,min(blocks,int(round(pct/100*blocks))))

    # The icon's CENTER is anchored exactly to the progress endpoint.
    # Bar and icon use the same percentage within the same track width.
    boxes=''.join([
        f'<span style="display:block;flex:1;height:14px;background:{fg if j<filled else "#dfe3e8"}"></span>'
        for j in range(blocks)
    ])
    pos=max(0,min(100,pct))
    st.markdown(f"""<div style="background:white;border:1px solid #d8dce2;padding:8px 14px 10px;margin:3px 0 8px">
      <div style="display:flex;justify-content:space-between;font-family:monospace;font-weight:700;font-size:15px;color:#14213d">
        <span>NEXT MILESTONE&nbsp;&nbsp;{nxt/1_000_000:g}M</span><span style="color:{fg}">{pct:.1f}% •</span>
      </div>
      <div style="position:relative;margin-top:4px;padding-top:72px">
        <img src="data:image/png;base64,{sprite}" style="position:absolute;left:{pos}%;bottom:17px;width:78px;height:70px;object-fit:contain;transform:translateX(-50%)">
        <div style="display:flex;gap:4px;width:100%;height:14px">{boxes}</div>
      </div>
      <div style="font-family:monospace;font-size:12px;color:#46516a;margin-top:5px">{prev/1_000_000:g}M</div>
    </div>""",unsafe_allow_html=True)

def history_panel(hist, cumulative_col, key, platform, title, daily_col=None):
    if hist.empty: return
    h=hist.copy()
    h[cumulative_col]=pd.to_numeric(h[cumulative_col],errors="coerce")
    h["date"]=h["date"].astype(str)
    h=h.sort_values("date").drop_duplicates("date",keep="last").reset_index(drop=True)
    if daily_col and daily_col in h.columns:
        h["daily_increase"]=pd.to_numeric(h[daily_col],errors="coerce")
        fallback=h[cumulative_col].diff()
        h["daily_increase"]=h["daily_increase"].where(h["daily_increase"].notna(),fallback)
    else:
        h["daily_increase"]=h[cumulative_col].diff()
    h["daily_increase"]=h["daily_increase"].fillna(0)
    # If same-day duplicates or missing first diff exist, keep later valid daily values visible.
    metric=st.radio("Graph",["Cumulative","1 Day Increase"],horizontal=True,key=key)
    col=cumulative_col if metric=="Cumulative" else "daily_increase"
    plot=h[["date",col]].dropna().copy()
    if not plot.empty:
        import altair as alt
        vals=plot[col].astype(float)
        lo=float(vals.min()); hi=float(vals.max())
        if metric=="Cumulative":
            span=max(hi-lo,1.0); pad=max(span*0.12,abs(hi)*0.0005,1.0)
            domain=[lo-pad,hi+pad]
        else:
            pad=max((hi-lo)*0.12,1.0); domain=[min(0,lo-pad),hi+pad]
        base=alt.Chart(plot).encode(
            x=alt.X("date:N",title="Date"),
            y=alt.Y(f"{col}:Q",title=metric,scale=alt.Scale(domain=domain,zero=False)),
            tooltip=["date:N",alt.Tooltip(f"{col}:Q",format=",")]
        )
        chart=(base.mark_bar() if metric=="1 Day Increase" else base.mark_line(point=True)).properties(height=300)
        st.altair_chart(chart,use_container_width=True)
    c1,c2=st.columns(2)
    with c1:
        st.download_button("⬇ GRAPH DATA",h.to_csv(index=False).encode("utf-8-sig"),
                           file_name=f"{platform.lower()}_{key}_history.csv",mime="text/csv",key=key+"_csv",
                           use_container_width=True)
    val=h[cumulative_col].dropna()
    if not val.empty:
        with c2:
            st.download_button("⬇ % CARD",card(platform,title,int(val.iloc[-1])),
                               file_name=f"{platform.lower()}_{key}_card.png",mime="image/png",key=key+"_card",
                               use_container_width=True)

