    if st.button("UPDATE YOUTUBE",type="primary",key="yt_update_top"):
        all_vids=query("SELECT song,video_id FROM youtube_videos WHERE active=1 ORDER BY id")
        now=datetime.now(); today=now.strftime("%Y-%m-%d")
        for r in all_vids.itertuples():
            try:
                vv=yt_views(r.video_id)
                execute("INSERT INTO youtube_data(collected_at,date,song,video_id,views) VALUES(%s,%s,%s,%s,%s)",
                        (now.isoformat(timespec="seconds"),today,r.song,r.video_id,vv))
            except Exception as e: st.warning(f"{r.song}: {e}")
        st.rerun()
    with st.expander("ADD VIDEO"):
        c1,c2,c3,c4=st.columns(4)
        song=c1.text_input("Title",key="ytaddtitle"); vid=c2.text_input("Video ID / URL",key="ytaddvid")
        album=c3.text_input("Album",key="ytaddalbum"); typ=c4.selectbox("Type",["MV","CONTENT"],key="ytaddtype")
        if st.button("ADD",key="ytadd"):
            x=re.search(r'(?:v=|youtu\.be/|shorts/)([\w-]{11})',vid); v=x.group(1) if x else vid.strip()
            execute("""INSERT INTO youtube_videos(song,video_id,active,video_type,album) VALUES(%s,%s,1,%s,%s)
                       ON CONFLICT(video_id) DO UPDATE SET song=EXCLUDED.song,video_type=EXCLUDED.video_type,album=EXCLUDED.album,active=1""",(song,v,typ,album)); st.rerun()
    vids=query("""SELECT id,song,title_fix.album,video_id,video_type,
                 (SELECT views FROM youtube_data d WHERE d.video_id=v.video_id ORDER BY date DESC,collected_at DESC LIMIT 1) AS views,
                 (SELECT date FROM youtube_data d WHERE d.video_id=v.video_id ORDER BY date DESC,collected_at DESC LIMIT 1) AS date
                 FROM youtube_videos v
                 CROSS JOIN LATERAL (SELECT COALESCE(v.album,'') album) title_fix
                 WHERE active=1 ORDER BY id""")
    if not vids.empty:
        vids=album_filter(vids,"yta")
        show=vids[["video_type","song","album","views","date"]].copy()
        show.columns=["Type","Title","Album","Current Views","Date"]
        show["Next Milestone"]=show["Current Views"].apply(lambda x:"—" if pd.isna(x) else f"{milestone(int(x))[1]:.1f}% → {milestone(int(x))[0]:,}")
        st.dataframe(show,use_container_width=True,hide_index=True)
        pick=st.selectbox("Graph / Card",vids.song.tolist(),key="ytpick")
        rr=vids[vids.song==pick].iloc[0]
        if pd.notna(rr.views): runner(rr.views,"YOUTUBE")
        hist=query("SELECT date,MAX(views) views FROM youtube_data WHERE video_id=%s GROUP BY date ORDER BY date",(rr.video_id,))
        history_panel(hist,"views","yt_hist","YOUTUBE",pick)
        if st.button("DELETE SELECTED VIDEO"):
            execute("UPDATE youtube_videos SET active=0 WHERE id=%s",(int(rr.id),)); st.rerun()

